def post(url, payload, headers=None, method=None):
    h = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}
    if headers:
        h.update(headers)
    req = urllib.request.Request(url, data=json.dumps(payload).encode(), headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=180) as r:
            sid = r.headers.get("mcp-session-id")
            raw = r.read().decode()
    except urllib.error.HTTPError as e:
        return {"http_error": e.code, "body": e.read().decode()[:300]}, None
    if "data:" in raw:
        raw = [ln[5:].strip() for ln in raw.splitlines() if ln.startswith("data:")][-1]
    return (json.loads(raw) if raw.strip() else {}), sid


class MCP:
    def __init__(self, port, ctx):
        self.port, self.ctx, self.n = port, ctx, 0
        _, self.sid = self._req("initialize", {"protocolVersion": "2025-03-26", "capabilities": {},
                                               "clientInfo": {"name": "oracle", "version": "0"}})
        try:
            post(f"http://localhost:{port}/mcp", {"jsonrpc": "2.0", "method": "notifications/initialized"},
                 {"mcp-session-id": self.sid or "", **self.ctx})
        except Exception:
            pass

    def _req(self, m, p):
        self.n += 1
        h = dict(self.ctx)
        if getattr(self, "sid", None):
            h["mcp-session-id"] = self.sid
        return post(f"http://localhost:{self.port}/mcp",
                    {"jsonrpc": "2.0", "id": self.n, "method": m, "params": p}, h)

    def call(self, name, args):
        r, _ = self._req("tools/call", {"name": name, "arguments": args})
        c = r.get("result", {}).get("content", [])
        text = "\n".join(x.get("text", "") for x in c if x.get("type") == "text")
        if text.startswith("❌") or r.get("result", {}).get("isError"):
            raise RuntimeError(f"{name} failed: {text[:300]}")
        try:
            return json.loads(text)
        except Exception:
            return text


def rec(resp, *keys):
    if isinstance(resp, list):
        resp = resp[0] if resp else {}
    if isinstance(resp, dict):
        for k in list(resp.keys()):
            if k in ("metadata",):
                continue
            inner = resp[k]
            # descend into a nested dict OR the first element of a nested list -- the
            # {"knowledges": [{...}]} shape every find/list tool returns.
            # MUST STAY IN SYNC with taskgen/gyms.py:rec() (tests/test_oracle_repair.py
            # asserts they agree; this copy exists so the bundle runs standalone).
            if isinstance(inner, list):
                inner = inner[0] if inner and isinstance(inner[0], dict) else None
            if isinstance(inner, dict):
                for key in keys:
                    if key in inner:
                        return inner[key]
        for key in keys:
            if key in resp:
                return resp[key]
    return None


VAR_WHOLE = re.compile(r"^\$vars\.([A-Za-z_][A-Za-z0-9_]*)$")
VAR_INTERP = re.compile(r"\{vars\.([A-Za-z_][A-Za-z0-9_]*)\}")


def resolve(v, vars):
    if isinstance(v, str):
        m = VAR_WHOLE.match(v)
        if m:
            return vars[m.group(1)]
        return VAR_INTERP.sub(lambda mm: str(vars[mm.group(1)]), v)
    if isinstance(v, dict):
        return {k: resolve(x, vars) for k, x in v.items()}
    if isinstance(v, list):
        return [resolve(x, vars) for x in v]
    return v


