dbids, sessions = {}, {}
for g in task["gym_servers_config"]:
    name, port = g["mcp_server_name"], PORTS[g["mcp_server_name"]]
    db = f"db_adopted_2c744514_{run_tag}_{name.replace('-', '_')}"
    import re as _re
    _dom = _re.search(r"db_(\w+?)_tron", Path(g["seed_database_file"]).name).group(1)
    sqlc = (BUNDLE / "environment" / "seeds" / ("seed_%s.sql" % _dom)).read_text()
    r, _ = post(f"http://localhost:{port}/api/seed-database",
                {"database_id": db, "name": db, "description": "oracle walkthrough",
                 "sql_content": sqlc})
    ok = r.get("success") or r.get("status") == "success" or (r.get("details") or {}).get("success") or r.get("data")
    assert ok, f"seed failed {name}: {str(r)[:200]}"
    dbids[name] = db
    sessions[name] = MCP(port, {"x-database-id": db, **g.get("context", {})})
