def coerce(args, arg_types):
    out = {}
    for k, v in args.items():
        t = arg_types.get(k, "")
        if t == "string" and isinstance(v, (int, float)) and not isinstance(v, bool):
            v = str(int(v) if isinstance(v, float) and v.is_integer() else v)
        elif t == "integer" and isinstance(v, str) and v.isdigit():
            v = int(v)
        out[k] = v
    return out


vars = {}
for step in STEPS:
    server = SERVER_BY_DOMAIN[step["gym"]]
    args = resolve(step.get("args", {}), vars)
    args = coerce(args, ARG_TYPES.get(step["tool"], {}))
    resp = sessions[server].call(step["tool"], args)
    for var, keys in step.get("save", {}).items():
        val = None
        for key in keys:
            if "." in key or "[" in key:
                cur = resp
                for part in key.split("."):
                    sel = re.match(r"^([A-Za-z_@][A-Za-z0-9_@]*)\[([A-Za-z_][A-Za-z0-9_]*)=(.*)\]$", part)
                    if sel:
                        k, field, want = sel.groups()
                        cur = cur.get(k) if isinstance(cur, dict) else None
                        if not isinstance(cur, list):
                            cur = None
                            break
                        cur = next((x for x in cur if isinstance(x, dict) and str(x.get(field)) == want), None)
                        continue
                    if isinstance(cur, list):
                        cur = cur[0] if cur else None
                    if not isinstance(cur, dict) or part not in cur:
                        cur = None
                        break
                    cur = cur[part]
                val = cur
            else:
                val = rec(resp, key)
            if val is not None:
                break
        if val is None:
            # a field that is PRESENT but null is a legitimate save (task18 turns on
            # employment_end_date STAYING null). Only a genuinely absent key is an error.
            # MUST STAY IN SYNC with taskgen/oracle_interp.py:extract_saves().
            leaf = keys[0].split(".")[-1].split("[")[0]
            stack, present = [resp], False
            while stack and not present:
                cur = stack.pop()
                if isinstance(cur, dict):
                    present = leaf in cur
                    stack.extend(cur.values())
                elif isinstance(cur, list):
                    stack.extend(cur)
            assert present, f"{step['step_id']}: save '{var}' keys {keys} not in {str(resp)[:200]}"
        vars[var] = val
    print(f"{step['step_id']} {step['tool']} ok" +
          (f" -> {[f'{k}={vars[k]}' for k in step.get('save', {})]}" if step.get("save") else ""))

print("\n========== VERIFIERS ==========")
passed = 0
for v in task["verifiers"]:
    gym = v["gym_name"]
    port, db = PORTS[gym], dbids[gym]
    q = v["validation_config"]["query"]
    exp = v["validation_config"]["expected_value"]
    r, _ = post(f"http://localhost:{port}/api/sql-runner", {"query": q, "database_id": db},
                {"x-database-id": db})
    data = r.get("data", [])
    val = list(data[0].values())[0] if data else None
    ok = val == exp
    passed += ok
    print(f"{'PASS' if ok else 'FAIL':4s} exp={exp} got={val}  {v['name'][:78]}")
print(f"\n{passed}/{len(task['verifiers'])} verifiers passed")
